        //   }
        // },
        // 3. 초안 본문 입력 필드 (멀티라인)
        {
          "type": "input",
          "block_id": "body_block",
          "label": { "type": "plain_text", "text": "초안 본문 내용" },
          "element": {
            "type": "plain_text_input",
            "action_id": "body_input", // ★ 데이터 추출 시 사용할 ID
            "multiline": true
          }
        },
        // 4. 이미지 생성 여부 체크박스
        {
          "type": "input",
          "block_id": "image_option_block", // 데이터 추출 ID 1
          "optional": true, // 체크 해제 가능하도록 설정
          "label": {
            "type": "plain_text",
            "text": "옵션 설정"
          },
          "element": {
            "type": "checkboxes",
            "action_id": "image_generation_checkbox", // 데이터 추출 ID 2
            "options": [
              {
                "text": {
                  "type": "plain_text",
                  "text": "이미지 생성 (DALL-E 3)"
                },
                "value": "generate_image" // 선택 시 전달될 값
              }
            ],
            // ★ 여기가 핵심: 아래 initial_options에 넣어두면 기본으로 체크됨
            // "initial_options": [
            //   {
