            //       "type": "plain_text",
            //       "text": "이미지 생성 (DALL-E 3)"
            //     },
            //     "value": "generate_image"
            //   }
            // ]
          }
        }
      ],
      "type": "modal"
    }
  }
];

return output;

// Slack에서 온 payload 데이터가 문자열로 되어 있어서 JSON으로 변환하는 코드입니다.
if (items[0].json.body.payload) {
  const payload = JSON.parse(items[0].json.body.payload);
  return [
    {
      json: payload
    }
  ];
} else {
  // payload가 없는 경우 (테스트 등)
  return items;
