  (() => {
    // 1. 카테고리 매핑 테이블
    const categoryMap = {
      "K-drama": 16,        
      "Korean Culture": 10, 
      "Korean Food": 14,    
      "Korean History": 15, 
      "Korean News": 12,    
      "Learning Korean": 13,
      "Travel to Korea": 11
    };

    // 2. 'Write Final' 노드의 결과 데이터 가져오기
    const geminiOutput = $('Write Final').item.json.output;

    // 3. 카테고리 ID 찾기 (매핑되는 게 없으면 기본값 13번 사용)
    const categoryId = categoryMap[geminiOutput.category] || 13;

    // 4. 최종 데이터 반환 
    return JSON.stringify({
      "title": geminiOutput.title,
      "content": geminiOutput.content,
      "slug": geminiOutput.rank_math_permalink,
      "status": "draft",
      "categories": [categoryId], 
      "meta": {
        "rank_math_focus_keyword": geminiOutput.rank_math_focus_keyword,
        "rank_math_title": geminiOutput.rank_math_title,
        "rank_math_description": geminiOutput.rank_math_description,
        "rank_math_permalink": geminiOutput.rank_math_permalink
      }
    });
  })()
}}

