={{
  (() => {
    // 1. 데이터 가져오기
    const threads = $json.output.threads || [];
    const blogUrl = $('Webhook').item.json.body.link || "https://podokorean.com";

    let blocks = [
      {
        "type": "header",
        "text": { "type": "plain_text", "text": "🧵 쓰레드 초안", "emoji": true }
      },
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": "대표님, 검토 부탁드립니다."
        }
      },
      { "type": "divider" }
    ];

    // 2. 반복문으로 포스트 생성
    threads.forEach((item, index) => {
      // (1) 영어 본문 처리 (링크 교체)
      let engText = item.english.replace('[[LINK]]', blogUrl);

      // (2) 마크다운 제거 (안전 장치)
      engText = engText.replace(/\*\*/g, "").replace(/\*/g, "");

      // (3) 이모지 깨짐 방지 인코딩 (URL용)
      // * 핵심: encodeURIComponent만 사용하되, 혹시 모를 앞뒤 공백 제거
      const urlEncoded = encodeURIComponent(engText.trim());
      const url = `https://www.threads.net/intent/post?text=${urlEncoded}`;

      // --- 블록 조립 ---

      // A. 번호 및 한국어 해석 (검토용)
      blocks.push({
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": `*📌 ${index + 1}번 스레드 (한국어 요약)*\n> ${item.korean}`
        }
      });

      // B. 영어 원문 (복사용 코드 블록)
      // Slack에서 ```text``` 안에 넣으면 복사하기가 매우 쉬워집니다.
      blocks.push({
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": `👇 *아래 영문을 복사하세요:*\n\`\`\`${engText}\`\`\``
        }
      });

      // C. 버튼 (1번 포스트만 제공)
      if (index === 0) {
        blocks.push({
          "type": "actions",
          "elements": [
            {
              "type": "button",
              "text": { "type": "plain_text", "text": "📝 작성창 띄우기", "emoji": true },
              "style": "primary",
              "url": url
            }
          ]
        });
      } else {
        // 2번부터는 안내 문구
        blocks.push({
          "type": "context",
          "elements": [
            { "type": "mrkdwn", "text": "↳ 위 텍스트를 복사해서 *이전 글의 답글*로 붙여넣으세요." }
          ]
        });
      }

      blocks.push({ "type": "divider" });
    });

    return { "blocks": blocks };
  })()
}}
